import { Vercel } from '@vercel/sdk';

const vercel = new Vercel({
  bearerToken: process.env.VERCEL_TOKEN!,
});

// List the 5 most recent deployments for a project
async function listDeployments(projectId: string): Promise<void> {
  const result = await vercel.deployments.getDeployments({
    projectId,
    limit: 5,
  });

  for (const deployment of result.deployments) {
    console.log(
      `[${deployment.state}] ${deployment.url} — ${new Date(
        deployment.createdAt
      ).toISOString()}`
    );
  }
}

listDeployments('prj_your_project_id').catch(console.error);

// app/api/hello/route.ts  (Next.js App Router)
import { NextRequest, NextResponse } from 'next/server';

export const runtime = 'edge'; // optional: run on Vercel Edge Network

export async function GET(req: NextRequest): Promise<NextResponse> {
  const { searchParams } = new URL(req.url);
  const name = searchParams.get('name') ?? 'World';

  return NextResponse.json(
    { message: `Hello, ${name}!`, timestamp: Date.now() },
    { status: 200 }
  );
}

export async function POST(req: NextRequest): Promise<NextResponse> {
  const body = await req.json() as { name?: string };

  if (!body.name) {
    return NextResponse.json({ error: 'name is required' }, { status: 400 });
  }

  return NextResponse.json({ message: `Hello, ${body.name}!` }, { status: 201 });
}
